#!/usr/bin/env python3
"""drug/vina_gnina_dock — auto-generated run.py (archetype=drug).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "drug"
BRAIN = "drug"
SKILL = "vina_gnina_dock"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'vina_gnina_dock', 'n_compounds': 0, 'best_score': 0.0, 'compound_csv': '', 'diagnostics': {'brain': 'drug', 'archetype': 'drug'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """drug brain 视角的 vina dock(praxis-drug env 有 vina 1.2.6;不依赖 gnina)。
    输入:receptor_pdb / ligand_sdf / box_center (可选) / num_modes / exhaustiveness
    输出:best_affinity / poses[]
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    receptor = payload.get("receptor_pdb")
    ligand = payload.get("ligand_sdf") or payload.get("ligand")
    n_modes = int(payload.get("num_modes", 9))
    exhaustiveness = int(payload.get("exhaustiveness", 8))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="vina_drug_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "out_dir": out_dir, "n_modes": n_modes}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "receptor": receptor or "", "ligand": ligand or "",
                "best_affinity": 0.0,
                "poses": [{"rank": 1, "affinity_kcal_per_mol": 0.0, "pose_path": ""}],
                "runtime_sec": 0.0, "diagnostics": {**diagnostics, "dry": True}}
    if not receptor or not _os.path.isfile(receptor):
        return {"ok": False, "error": f"receptor_pdb 不存在: {receptor!r}", "diagnostics": diagnostics}
    if not ligand or not _os.path.isfile(ligand):
        return {"ok": False, "error": f"ligand 不存在: {ligand!r}", "diagnostics": diagnostics}

    out_sdf = _os.path.join(out_dir, "docked.sdf")
    cmd = ["vina", "--receptor", receptor, "--ligand", ligand, "--autobox_ligand", ligand,
           "--exhaustiveness", str(exhaustiveness), "--num_modes", str(n_modes), "--out", out_sdf]
    t0 = _time.time()
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "vina 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    poses = []
    for ln in r["stdout"].splitlines():
        parts = ln.split()
        if len(parts) >= 4 and parts[0].isdigit():
            try:
                poses.append({"rank": int(parts[0]),
                              "affinity_kcal_per_mol": float(parts[1]),
                              "pose_path": out_sdf})
            except ValueError:
                continue
    best = poses[0]["affinity_kcal_per_mol"] if poses else 0.0
    return {"ok": True, "skill_id": SKILL,
            "receptor": receptor, "ligand": ligand,
            "best_affinity": best, "poses": poses,
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
